if(!defined('IN_LAYOUT')){http_response_code(403);return;}require_once __DIR__.'/../../../classes/system/ReleaseNotes.php';if(OfficePolicy::actor($db,(int)$uid)['role']!=='super_admin'){http_response_code(403);return;}$releaseStore=new ReleaseNotes($db);$_SESSION['release_csrf']=$_SESSION['release_csrf']??bin2hex(random_bytes(32));$releaseError='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{if(!is_string($_POST['release_csrf']??null)||!hash_equals($_SESSION['release_csrf'],$_POST['release_csrf']))throw new RuntimeException('Reload before publishing.');$published=$releaseStore->append((int)$uid,$_POST);$_SESSION['release_success']='Version '.$published.' is now visible on the public Patch notes page.';header('Location: layout.php?page=patch_notes');exit;}catch(Throwable $e){$releaseError=$e instanceof PDOException?'The release could not be published. Please try again.':$e->getMessage();}
