?><link rel="stylesheet" href="../assets/css/office-tools.css?v=20261029-1"><section class="ot-workspace"><header class="ot-heading"><div><p class="ot-eyebrow">SUPERADMIN · WEBSITE UPDATES</p><h1>Patch notes</h1><p>Append a version so everyone can see what changed.</p></div><a class="ot-button" href="../patch_notes.php">View public patch notes</a></header><?php if($releaseError):?><p class="ot-alert error" role="alert"><?=$rtE($releaseError)?></p><?php endif;?><?php if(!empty($_SESSION['release_success'])):?><p class="ot-alert" role="status"><?=$rtE($_SESSION['release_success'])?></p><?php unset($_SESSION['release_success']);endif;?><div class="ot-columns"><form method="post" data-portal-save class="ot-card" id="releaseNoteForm"><input type="hidden" name="release_csrf" value="<?=$rtE($_SESSION['release_csrf'])?>"><h2>Publish a new version</h2><p class="ot-help">Visible to everyone. Use short public-facing descriptions. Published versions stay in the release history.</p><div class="ot-grid"><label>Version *<input name="version" maxlength="30" pattern="[0-9]+\.[0-9]+\.[0-9]+" required value="<?=$rtE(is_string($_POST['version']??null)?$_POST['version']:$suggested)?>"><small>Latest: <?=$rtE($latest)?>. Example: <?=$rtE($suggested)?></small></label><label>Release date *<input type="date" name="release_date" required max="<?=date('Y-m-d')?>" value="<?=$rtE(is_string($_POST['release_date']??null)?$_POST['release_date']:date('Y-m-d'))?>"></label></div><label>Release title *<input name="title" maxlength="150" required placeholder="e.g. Easier paper PDS entry" value="<?=$rtE(is_string($_POST['title']??null)?$_POST['title']:'')?>"></label><fieldset class="ot-changes"><legend>What changed *</legend><div id="releaseRows"><?php foreach($rows as $index=>$row):if(!is_array($row))continue;?><div class="ot-change-row"><label>Short label<input name="items[<?=(int)$index?>][label]" maxlength="70" placeholder="e.g. Personal data sheets" value="<?=$rtE(is_string($row['label']??null)?$row['label']:'')?>"></label><label>Description<textarea name="items[<?=(int)$index?>][detail]" maxlength="1000" rows="2" placeholder="Explain the improvement in plain language."><?=$rtE(is_string($row['detail']??null)?$row['detail']:'')?></textarea></label><button type="button" class="ot-text-button" data-release-remove>Remove change</button></div><?php endforeach;?></div><button type="button" class="ot-button" data-release-add>Add change</button></fieldset><p class="ot-help">Keep student information, passwords, account details and private records out of public notes.</p><button class="ot-button primary" type="submit">Publish version</button></form><aside class="ot-card"><h2>Release history</h2><p class="ot-help">New versions are appended. Earlier releases remain available.</p><ol class="ot-release-history"><?php foreach($releases as $i=>$r):?><li><span class="ot-release-version">v<?=$rtE($r['version'])?> <?=$i===0?'<small>Latest</small>':''?></span><strong><?=$rtE($r['title'])?></strong><time><?=$rtE(date('M j, Y',strtotime($r['date'])))?></time><a href="../patch_notes.php#version-<?=$rtE($r['version'])?>">Read changes</a></li><?php endforeach;?></ol></aside></div></section><script src="../assets/js/office-tools.js?v=20261029-1"></script>
